import {
  Node_Type,
  type Media,
  type SmartBlockCellNode,
  type SmartBlockData_Orientation,
  type SmartBlockData_Type,
} from './../../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../../ricos-types/index.js';
import type { PmSmartBlockCellNode } from './../../_shared/pm-node-types.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';

// Parent context that both PM and JTD adapters need supplied externally:
// each side derives it from its own data model before calling the adapter.
//
//  - PM: parent ProseMirror node attrs + childCount + $pos.index().
//  - JTD: parentNode.smartBlockData + nodes.length + the cell's own nodeIndex.
//
// Why externalised: PM cells receive their parent state via ProseMirror's
// resolver (which needs `editor` + `getPos`), and JTD cells receive it via
// `RicosNodeContext`. Keeping the adapter ignorant of how the parent was
// resolved lets it be a pure transform.
export type CellParentContext = {
  type: SmartBlockData_Type;
  columnSize: string;
  orientation: SmartBlockData_Orientation;
  totalCells: number;
  cellIndex: number;
  isShapesMode: boolean;
};

// Normalised cell shape consumed by SmartBlockCellView. Both PM and JTD
// adapters converge on this type, so the renderer no longer branches on data
// source.
export type CellViewModel = {
  type: SmartBlockData_Type;
  cellIndex: number;
  totalCells: number;
  columnSize: string;
  orientation: SmartBlockData_Orientation;
  isShapesMode: boolean;
  // Optional because JTD `SmartBlockCellNode.id` is optional (PM always sets
  // one). When absent the renderer falls back to `data-smart-block-cell={true}`
  // — the same shape the parseDOM rule in `smart-block-cell-extension.ts:119`
  // emits.
  cellId?: string;

  cellColors: {
    accentColor?: string;
    backgroundColor?: string;
    borderColor?: string;
    borderWidth?: number;
    borderRadius?: number;
  };
  shape?: Media;
  shapeColor?: string;

  // Pass-through of the cell's stored label. Cell-creation paths seed
  // DEFAULT_LABEL ('50%') for stat variants and DEFAULT_STAR_RATING_LABEL for
  // star ratings; an explicit null here means the user cleared it and the
  // input/value should render empty (placeholder shows in the editor).
  label: string | null;

  // SMALL_BULLETS reads these to scale the ::marker — mirrors the
  // bulleted-list pattern in `list-item-sizing.ts`. fontSize is the resolved
  // CSS value: JTD stores it as a numeric pixel value (FontSizeData.value);
  // PM marks store either a number or a string like '24px'. Both are valid
  // values for React's `style.fontSize`. headingLevel is set only when the
  // cell's first child is a heading.
  contentStyle: {
    fontSize?: string | number;
    headingLevel?: number;
  };
};

const nullToUndef = <T>(value: T | null | undefined): T | undefined =>
  value === null || value === undefined ? undefined : value;

export const pmCellToViewModel = (pmNode: PmNode, parent: CellParentContext): CellViewModel => {
  const attrs = pmNode.attrs as PmSmartBlockCellNode['attrs'];
  const { type } = parent;

  return {
    type,
    cellIndex: parent.cellIndex,
    totalCells: parent.totalCells,
    columnSize: parent.columnSize,
    orientation: parent.orientation,
    isShapesMode: parent.isShapesMode,
    cellId: attrs.id,
    cellColors: {
      accentColor: nullToUndef(attrs.accentColor),
      backgroundColor: nullToUndef(attrs.backgroundColor),
      borderColor: nullToUndef(attrs.borderColor),
      borderWidth: nullToUndef(attrs.borderWidth),
      borderRadius: nullToUndef(attrs.borderRadius),
    },
    shape: nullToUndef(attrs.shape),
    shapeColor: nullToUndef(attrs.shapeColor),
    label: attrs.label ?? null,
    contentStyle: getPmCellContentStyle(pmNode, type),
  };
};

// Narrow PM read: only touches the first inline of the first block when the
// variant is SMALL_BULLETS. Avoids walking the full converter pipeline on the
// hot editor render path (every keystroke re-renders cells).
const getPmCellContentStyle = (
  pmNode: PmNode,
  type: SmartBlockData_Type
): CellViewModel['contentStyle'] => {
  if (type !== 'SMALL_BULLETS') {
    return {};
  }
  const firstBlock = pmNode.firstChild;
  if (!firstBlock) {
    return {};
  }
  const headingLevel =
    firstBlock.type.name === PmNodeType.HEADING
      ? (firstBlock.attrs.level as number | undefined)
      : undefined;
  const fontSize = firstBlock.firstChild?.marks.find(m => m.type.name === Decoration_Type.FONT_SIZE)
    ?.attrs.value as string | undefined;
  return { fontSize, headingLevel };
};

export const ricosCellToViewModel = (
  cellNode: SmartBlockCellNode,
  parent: CellParentContext
): CellViewModel => {
  const cellData = cellNode.smartBlockCellData;
  const { type } = parent;

  const label = cellData && 'label' in cellData ? (cellData.label ?? null) : null;

  return {
    type,
    cellIndex: parent.cellIndex,
    totalCells: parent.totalCells,
    columnSize: parent.columnSize,
    orientation: parent.orientation,
    isShapesMode: parent.isShapesMode,
    cellId: cellNode.id,
    cellColors: {
      accentColor: cellData && 'accentColor' in cellData ? cellData.accentColor : undefined,
      backgroundColor:
        cellData && 'backgroundColor' in cellData ? cellData.backgroundColor : undefined,
      borderColor: cellData && 'borderColor' in cellData ? cellData.borderColor : undefined,
      borderWidth: cellData && 'borderWidth' in cellData ? cellData.borderWidth : undefined,
      borderRadius: cellData && 'borderRadius' in cellData ? cellData.borderRadius : undefined,
    },
    shape: cellData && 'shape' in cellData ? cellData.shape : undefined,
    shapeColor: cellData && 'shapeColor' in cellData ? cellData.shapeColor : undefined,
    label,
    contentStyle: getRicosCellContentStyle(cellNode, type),
  };
};

const getRicosCellContentStyle = (
  cellNode: SmartBlockCellNode,
  type: SmartBlockData_Type
): CellViewModel['contentStyle'] => {
  if (type !== 'SMALL_BULLETS') {
    return {};
  }
  const firstChild = cellNode.nodes?.[0];
  if (!firstChild) {
    return {};
  }
  const headingLevel =
    firstChild.type === Node_Type.HEADING
      ? (firstChild.headingData?.level ?? undefined)
      : undefined;
  const firstInline = firstChild.nodes?.[0];
  const fontSize =
    firstInline && 'textData' in firstInline
      ? firstInline.textData?.decorations?.find(d => d.type === Decoration_Type.FONT_SIZE)
          ?.fontSizeData?.value
      : undefined;
  return { fontSize, headingLevel };
};
