import { LayoutTwoColumns } from '@wix/wix-ui-icons-common/lazy';

import { Node_Type } from './../ricos-types/index.js';
import type { AddButton, RicosServices } from './../ricos-types/index.js';
import { TOOLBARS } from './../editor-common/index.js';

import { DATA_HOOKS } from './data-hooks.js';
import { SMART_BLOCK_VARIANT_PICKER_MODAL_ID, VariantPicker } from './modals/variant-picker.js';
import type { SmartBlockPluginEditorConfig } from './types.js';

export const smartBlockAddToolbars: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.MOBILE,
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
];

export const getAddButtons = (
  _config: SmartBlockPluginEditorConfig | undefined,
  services: RicosServices
): AddButton[] => {
  const {
    modals,
    context: { isMobile },
  } = services;

  return [
    {
      id: Node_Type.SMART_BLOCK,
      label: 'SmartBlock_InsertButton_Label',
      dataHook: DATA_HOOKS.INSERT_BUTTON,
      icon: LayoutTwoColumns,
      tooltip: 'SmartBlock_InsertButton_Tooltip',
      toolbars: smartBlockAddToolbars,
      command: ({ referenceElement }) => {
        modals.togglePluginPanel({
          id: SMART_BLOCK_VARIANT_PICKER_MODAL_ID,
          Component: VariantPicker,
          componentProps: {},
          isMobile,
          positioning: {
            referenceElement,
            placement: 'bottom',
          },
        });

        return true;
      },
      menuConfig: {
        tags: 'SmartBlock_plugin_search_tags',
      },
    },
  ];
};
