import type { CSSProperties } from 'react';

import type {
  SmartBlockData_Orientation,
  SmartBlockData_Type,
} from './../../ricos-schema/next-schema/index.js';
import type { CustomSmartBlockStyle } from './../../ricos-types/theme-types.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';

import { resolveSmartBlockCssColor } from './resolve-smart-block-css-color.js';
import { getCellColorAttr } from './variant-features.js';

type CellDesignAttrs = {
  accentColor?: string | null;
  backgroundColor?: string | null;
  borderColor?: string | null;
  borderWidth?: number | null;
  borderRadius?: number | null;
};

// Single composed entry point used by both the editor and viewer cell
// renderers. Emits the cell-level CSS custom properties as a flat bag; each
// variant's SCSS consumes only the vars it needs, so unused vars are inert
// (a line variant that never reads --ricos-internal-sb-bg is structurally immune to a
// stray bg colour).
//
// Vars:
//   --ricos-internal-sb-bg                   Cell background. Solid variants paint
//                                   this; others ignore. Theme backgroundColor
//                                   folded in only for variants whose
//                                   getCellColorAttr is 'backgroundColor'.
//   --ricos-internal-sb-accent               Cell accent. Always set when accent is
//                                   non-null; preserves the literal
//                                   `transparent` so consumers can explicitly
//                                   hide themselves (SMALL_BULLETS marker,
//                                   line variants, bullets, PROCESS_STEPS).
//   --ricos-internal-sb-accent-opaque        Set only when accent is non-null and
//                                   non-transparent. Chip variants (TIMELINE
//                                   / MINIMAL_TIMELINE / PILLS) read this so a
//                                   transparent picker pick falls back to the
//                                   default colour instead of vanishing.
//   --ricos-internal-sb-border-color/-width/-radius
//                                   Cell border. Variants without border
//                                   schema leave width unset → 0 → inert.
//                                   Theme borderColor folded in uniformly;
//                                   QUOTE_BOXES (no borderWidth in schema)
//                                   collapses to no border and draws via
//                                   ::before using --ricos-internal-sb-accent.
//   --ricos-internal-sb-grid-col / -grid-row Per-cell grid placement. Set only for
//                                   the three grid-laying variants
//                                   (SOLID_BOXES_ALTERNATING / TIMELINE /
//                                   MINIMAL_TIMELINE) since the math differs
//                                   per variant.
export const computeSmartBlockCellVars = (
  cellAttrs: CellDesignAttrs,
  themeSmartBlock: CustomSmartBlockStyle | undefined,
  type: SmartBlockData_Type,
  cellIndex: number,
  orientation: SmartBlockData_Orientation = 'HORIZONTAL'
): CSSProperties => {
  const colorAttr = getCellColorAttr(type);
  const backgroundColor =
    colorAttr === 'backgroundColor'
      ? (cellAttrs.backgroundColor ?? themeSmartBlock?.backgroundColor)
      : cellAttrs.backgroundColor;
  const accentColor =
    colorAttr === 'accentColor'
      ? (cellAttrs.accentColor ?? themeSmartBlock?.accentColor)
      : cellAttrs.accentColor;
  const borderColor = cellAttrs.borderColor ?? themeSmartBlock?.borderColor;
  const { borderWidth, borderRadius } = cellAttrs;

  const vars: Record<string, string> = {};

  if (backgroundColor && backgroundColor !== TRANSPARENT_HEX_COLOR) {
    const resolved = resolveSmartBlockCssColor(backgroundColor);
    if (resolved) {
      vars['--ricos-internal-sb-bg'] = resolved;
    }
  }

  if (accentColor) {
    if (accentColor === TRANSPARENT_HEX_COLOR) {
      vars['--ricos-internal-sb-accent'] = 'transparent';
    } else {
      const resolved = resolveSmartBlockCssColor(accentColor);
      if (resolved) {
        vars['--ricos-internal-sb-accent'] = resolved;
        vars['--ricos-internal-sb-accent-opaque'] = resolved;
      }
    }
  }

  if (borderColor) {
    if (borderColor === TRANSPARENT_HEX_COLOR) {
      // Preserve an explicit transparent pick so it overrides any host CSS
      // that paints a default border. Matches the block-level treatment in
      // computeSmartBlockWrapperVars and the accent treatment above.
      vars['--ricos-internal-sb-border-color'] = 'transparent';
    } else {
      const resolved = resolveSmartBlockCssColor(borderColor);
      if (resolved) {
        vars['--ricos-internal-sb-border-color'] = resolved;
      }
    }
  }
  if (borderWidth && borderWidth > 0) {
    vars['--ricos-internal-sb-border-width'] = `${borderWidth}px`;
  }
  if (borderRadius && borderRadius > 0) {
    vars['--ricos-internal-sb-border-radius'] = `${borderRadius}px`;
  }

  const gridPlacement =
    type === 'SOLID_BOXES_ALTERNATING'
      ? getCheckerboardGridStyle(cellIndex, orientation)
      : type === 'TIMELINE' || type === 'MINIMAL_TIMELINE'
        ? getTimelineGridStyle(cellIndex, orientation)
        : // PYRAMID and VERTICAL_FUNNEL drive their clip-path and centroid
          // math from `--ricos-internal-sb-cell-index`; the formulas differ
          // per-variant in SCSS but both need the same per-cell index.
          type === 'PYRAMID' || type === 'VERTICAL_FUNNEL'
          ? { '--ricos-internal-sb-cell-index': `${cellIndex}` }
          : undefined;

  if (type === 'STAIRCASE') {
    vars['--ricos-internal-sb-cell-index'] = `${cellIndex}`;
  }

  return { ...vars, ...gridPlacement } as CSSProperties;
};

const getCheckerboardGridStyle = (
  cellIndex: number,
  orientation: 'HORIZONTAL' | 'VERTICAL' = 'HORIZONTAL'
): Record<string, string> => {
  if (orientation === 'VERTICAL') {
    const row = cellIndex + 1;
    const col = cellIndex % 2 === 0 ? 1 : 2;
    return {
      '--ricos-internal-sb-grid-col': `${col}`,
      '--ricos-internal-sb-grid-row': `${row}`,
    };
  }
  return {
    '--ricos-internal-sb-grid-col': `${cellIndex + 1}`,
    '--ricos-internal-sb-grid-row': `${cellIndex % 2 === 0 ? 1 : 2}`,
  };
};

// Timeline grid placement: each cell spans 3 sub-columns of a (2N+1)-column
// grid (horizontal) so its content extends from the previous chip to the next,
// while the chip itself sits centered in the middle sub-column. Vertical mode
// keeps the simple alternating-side layout — one row per cell.
const getTimelineGridStyle = (
  cellIndex: number,
  orientation: 'HORIZONTAL' | 'VERTICAL' = 'HORIZONTAL'
): Record<string, string> => {
  if (orientation === 'VERTICAL') {
    return {
      '--ricos-internal-sb-grid-col': cellIndex % 2 === 0 ? '1' : '2',
      '--ricos-internal-sb-grid-row': `${cellIndex + 1}`,
    };
  }
  return {
    '--ricos-internal-sb-grid-col': `${2 * cellIndex + 1}`,
    '--ricos-internal-sb-grid-row': `${cellIndex % 2 === 0 ? 1 : 2}`,
  };
};
