import type { CSSProperties } from 'react';

import type { SmartBlockData_Type } from './../../ricos-schema/next-schema/index.js';
import type { CustomSmartBlockStyle } from './../../ricos-types/theme-types.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';

import { resolveSmartBlockCssColor } from './resolve-smart-block-css-color.js';

// Block (wrapper) attrs. Only SOLID_JOINED_BOXES carries these on its data —
// the var emission is variant-agnostic so other variants harmlessly pass
// undefined fields and get an empty bag back.
type BlockDesignAttrs = {
  borderColor?: string | null;
  borderWidth?: number | null;
  borderRadius?: number | null;
};

// Single composed entry point used by both the editor and viewer wrappers.
// Emits the wrapper-level CSS custom properties on a flat bag; each variant's
// SCSS consumes only the vars it needs, so unused vars are inert.
//
// Vars:
//   --ricos-internal-sb-cols                 cell count, read by the grid-template
//                                   `repeat(...)` on SOLID_BOXES_ALTERNATING /
//                                   TIMELINE / MINIMAL_TIMELINE. Set on every
//                                   variant; non-grid variants ignore it.
//   --ricos-internal-sb-block-border-color   SOLID_JOINED_BOXES wrapper border + the
//                                   connecting line on the three grid variants.
//                                   Theme borderColor folded in as a fallback.
//   --ricos-internal-sb-block-border-width   SOLID_JOINED_BOXES wrapper border.
//   --ricos-internal-sb-block-border-radius  SOLID_JOINED_BOXES wrapper border, plus
//                                   joined-box cell-corner inner-radius math
//                                   in CSS (max/calc).
export const computeSmartBlockWrapperVars = (
  blockAttrs: BlockDesignAttrs,
  themeSmartBlock: CustomSmartBlockStyle | undefined,
  type: SmartBlockData_Type,
  cellCount: number
): CSSProperties => {
  // Block-level border schema only belongs on SOLID_JOINED_BOXES. For other
  // variants the stored attrs are stale leftovers from a prior switch and
  // must be ignored — the TIMELINE / ALTERNATING / MINIMAL_TIMELINE connector
  // line still picks up the theme border colour via the themeSmartBlock
  // fallback.
  const isJoinedBoxes = type === 'SOLID_JOINED_BOXES';
  const borderColor = isJoinedBoxes
    ? (blockAttrs.borderColor ?? themeSmartBlock?.borderColor)
    : themeSmartBlock?.borderColor;
  const borderWidth = isJoinedBoxes ? blockAttrs.borderWidth : undefined;
  const borderRadius = isJoinedBoxes ? blockAttrs.borderRadius : undefined;

  const vars: Record<string, string | number> = {
    '--ricos-internal-sb-cols': cellCount,
  };

  if (borderColor) {
    if (borderColor === TRANSPARENT_HEX_COLOR) {
      vars['--ricos-internal-sb-block-border-color'] = 'transparent';
    } else {
      const resolved = resolveSmartBlockCssColor(borderColor);
      if (resolved) {
        vars['--ricos-internal-sb-block-border-color'] = resolved;
      }
    }
  }
  if (borderWidth && borderWidth > 0) {
    vars['--ricos-internal-sb-block-border-width'] = `${borderWidth}px`;
  }
  if (borderRadius && borderRadius > 0) {
    vars['--ricos-internal-sb-block-border-radius'] = `${borderRadius}px`;
  }

  return vars as CSSProperties;
};
