import type { CSSProperties } from 'react';

const COLUMN_SIZE_TO_COLS: Record<string, number> = {
  SMALL: 4,
  MEDIUM: 3,
  LARGE: 2,
  EXTRA_LARGE: 1,
};

const RESPONSIVE_COLS: Record<string, number> = {
  SMALL: 2,
  MEDIUM: 2,
  LARGE: 1,
  EXTRA_LARGE: 1,
};

export const getColumnsPerRow = (columnSize: string): number =>
  COLUMN_SIZE_TO_COLS[columnSize] ?? 3;

export const getResponsiveColumnsPerRow = (columnSize: string): number =>
  RESPONSIVE_COLS[columnSize] ?? 2;

// Cell position data-attrs for SCSS to target last-row layout overrides
// (`[data-last-row][data-last-row-cells="N"]`). Takes the column size and
// computes the per-cell last-row state internally — callers only need to know
// where the cell sits, not how the grid wraps.
export const getCellPositionDataAttrs = (
  cellIndex: number,
  totalCells: number,
  columnSize: string
) => {
  const lrp = calculateLastRowPosition(
    cellIndex,
    totalCells,
    getColumnsPerRow(columnSize),
    getResponsiveColumnsPerRow(columnSize)
  );

  return {
    'data-cell-index': cellIndex,
    'data-cells-total': totalCells,
    'data-last-row': lrp.isInLastRow || undefined,
    'data-last-row-cells': lrp.isInLastRow ? lrp.cellsInLastRow : undefined,
    'data-last-row-2col': lrp.isInLastRow2Col || undefined,
    'data-last-row-cells-2col': lrp.isInLastRow2Col ? lrp.cellsInLastRow2Col : undefined,
  };
};

const calculateLastRowPosition = (
  cellIndex: number,
  totalCells: number,
  columnsPerRow: number,
  responsiveColumnsPerRow: number
) => {
  const cellsInLastRow = totalCells % columnsPerRow || columnsPerRow;
  const lastRowStart = totalCells - cellsInLastRow;

  const cellsInLastRow2 = totalCells % responsiveColumnsPerRow || responsiveColumnsPerRow;
  const lastRowStart2 = totalCells - cellsInLastRow2;

  return {
    isInLastRow: cellIndex >= lastRowStart,
    cellsInLastRow,
    isInLastRow2Col: cellIndex >= lastRowStart2,
    cellsInLastRow2Col: cellsInLastRow2,
  };
};

// CIRCLE variant: cells stack in two vertical columns (left and right of the
// donut) so long content never overlaps. Each cell's vertical rank within its
// column is derived from the segment's angle — segments closer to TOP get
// smaller row indices.
//
// Geometry: cell 0's segment ENDS at the top of the donut, so its midpoint
// sits just left of vertical (-180°/N). The remaining cells continue clockwise.
// This keeps cells balanced left/right for even N (e.g. N=6 gives 3 left /
// 3 right) and puts item 1 in the top-left corner in natural reading order.
// Examples: N=4 → cell 0 mid = -45° (NW corner). N=6 → cell 0 mid = -30°
// (just left of top, then 30°, 90°, 150°, 210°, 270°).
// Special case: with a single cell the segment is a full ring; place the label
// on the left. Shared with the donut SVG geometry in components/circle-donut.tsx
// so segment midpoints and label positions cannot drift.
export const getCellMidAngleDeg = (cellIndex: number, totalCells: number): number => {
  if (totalCells <= 1) {
    return -90;
  }
  return -180 / totalCells + cellIndex * (360 / totalCells);
};

// True when this cell's segment sits exactly at the bottom of the donut (mid-
// angle == 180°). Only odd N produces such a cell — for N=5 it's index 3, for
// N=3 it's index 2, etc. Used to route that one cell into the third "bottom"
// lane (below the donut, centered) instead of the left/right column it would
// otherwise fall into via the sin-of-180° floating-point fluke.
const isBottomCenterCell = (cellIndex: number, totalCells: number): boolean => {
  if (totalCells <= 1) {
    return false;
  }
  return Math.abs(getCellMidAngleDeg(cellIndex, totalCells) - 180) < 1e-6;
};

// N=1 is a special-case single full ring — the cell is anchored on the left
// (see getCellMidAngleDeg), not at the bottom. Only N=3, 5, 7… produce a real
// bottom-center cell.
export const hasBottomCenterCell = (totalCells: number): boolean =>
  totalCells >= 3 && totalCells % 2 === 1;

export const getCircleCellStyle = (
  cellIndex: number,
  totalCells: number
): { style: CSSProperties; side: 'left' | 'right' | 'bottom'; row: number } => {
  if (isBottomCenterCell(cellIndex, totalCells)) {
    // Bottom-center cell sits in the trailing `auto` track that the .circle
    // wrapper allocates (see smart-block-view.tsx). Side cells occupy rows
    // 1..(N-1)/2, so the bottom cell goes into row (N+1)/2. An explicit row
    // is required because grid auto-placement would otherwise fill the empty
    // column-2 slot in row 1 (which is the donut-spanned area) rather than
    // landing in the trailing auto track beneath the donut.
    const row = (totalCells + 1) / 2;
    return {
      style: { '--ricos-internal-sb-row': `${row}` } as CSSProperties,
      side: 'bottom',
      row,
    };
  }

  const midAngleDeg = getCellMidAngleDeg(cellIndex, totalCells);
  const side: 'left' | 'right' = Math.sin((midAngleDeg * Math.PI) / 180) >= 0 ? 'right' : 'left';

  // `getCellMidAngleDeg` lays cells clockwise starting just left of TOP. So the
  // right column is filled by indices 1..floor(N/2) in top-down order, and the
  // left column by [0, N-1, N-2, …] in top-down order — both expressible as
  // O(1) index math. Stay in lock-step with `getCellMidAngleDeg`'s ordering.
  const row = side === 'right' ? cellIndex : ((totalCells - cellIndex) % totalCells) + 1;

  return {
    style: { '--ricos-internal-sb-row': `${row}` } as CSSProperties,
    side,
    row,
  };
};
