import { definePmNodeConverter, type PmNodeJson } from './../pm-converters/types.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { SmartBlockCellData, SmartBlockCellNode } from './../ricos-schema/next-schema/index.js';
import type { PmSmartBlockCellNode } from './../_shared/pm-node-types.js';
import { unreachable } from './../_shared/uncreachable.js';

export const smartBlockCellConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.SMART_BLOCK_CELL],
    convert: (node, visit) => {
      // @ts-expect-error
      const data = node.smartBlockCellData;
      return {
        type: Node_Type.SMART_BLOCK_CELL,
        attrs: {
          id: node.id,
          type: data?.type ?? null,
          label: data?.label ?? null,
          shape: data?.shape ?? null,
          shapeColor:
            data?.shapeColor ??
            (Object.values((data?.shapeStyles?.colors as Record<string, string>) ?? {}).find(
              Boolean
            ) ||
              null),
          accentColor: data?.accentColor ?? null,
          backgroundColor: data?.backgroundColor ?? null,
          borderColor: data?.borderColor ?? null,
          borderWidth: data?.borderWidth ?? null,
          borderRadius: data?.borderRadius ?? null,
        },
        content: visit?.(node),
      };
    },
  },
  fromPm: {
    types: [Node_Type.SMART_BLOCK_CELL],
    // @ts-expect-error next node type
    convert: (node: PmNodeJson, visit: (node: PmNodeJson) => SmartBlockCellNode[]) => {
      const { attrs } = node as unknown as PmSmartBlockCellNode;
      const { id, type } = attrs;

      return {
        type: Node_Type.SMART_BLOCK_CELL,
        id,
        nodes: visit(node),
        smartBlockCellData: type ? smartBlockCellDataPerVariant(type, attrs) : undefined,
      };
    },
  },
});

const smartBlockCellDataPerVariant = (
  type: NonNullable<PmSmartBlockCellNode['attrs']['type']>,
  attrs: PmSmartBlockCellNode['attrs']
): SmartBlockCellData => {
  const {
    backgroundColor,
    accentColor,
    label,
    shape,
    shapeColor,
    borderColor,
    borderWidth,
    borderRadius,
  } = attrs;
  switch (type) {
    case 'SOLID_BOXES':
    case 'SOLID_BOXES_ALTERNATING':
      return {
        type,
        backgroundColor: backgroundColor ?? undefined,
        borderColor: borderColor ?? undefined,
        borderWidth: borderWidth ?? undefined,
        borderRadius: borderRadius ?? undefined,
      };
    case 'SOLID_JOINED_BOXES':
      return {
        type,
        backgroundColor: backgroundColor ?? undefined,
      };
    case 'SIDE_LINE_TEXT':
    case 'TOP_LINE_TEXT':
    case 'QUOTE_BOXES':
    case 'MINIMAL_TIMELINE':
      return {
        type,
        accentColor: accentColor ?? undefined,
      };
    case 'CIRCLE_STATS':
      return {
        type,
        accentColor: accentColor ?? undefined,
        label: label ?? undefined,
      };
    case 'OUTLINE_BOXES_WITH_TOP_CIRCLE':
    case 'PROCESS_STEPS':
    case 'TIMELINE':
    case 'PILLS':
    case 'CIRCLE':
    case 'PYRAMID':
    case 'STAIRCASE':
    case 'VERTICAL_FUNNEL':
      return {
        type,
        accentColor: accentColor ?? undefined,
        shape: shape ?? undefined,
        shapeColor: shapeColor ?? undefined,
      };
    case 'BAR_STATS':
    case 'STAR_RATING':
      return {
        type,
        accentColor: accentColor ?? undefined,
        label: label ?? undefined,
      };
    case 'STATS':
      return {
        type,
        accentColor: accentColor ?? undefined,
        label: label ?? undefined,
        borderColor: borderColor ?? undefined,
        borderWidth: borderWidth ?? undefined,
        borderRadius: borderRadius ?? undefined,
      };
    case 'SMALL_BULLETS':
      return {
        type,
        accentColor: accentColor ?? undefined,
        borderColor: borderColor ?? undefined,
        borderWidth: borderWidth ?? undefined,
        borderRadius: borderRadius ?? undefined,
      };
    case 'NUMBERED_BOXES':
    case 'BIG_BULLETS':
    case 'ARROW_BULLETS':
      return {
        type,
        accentColor: accentColor ?? undefined,
        shape: shape ?? undefined,
        shapeColor: shapeColor ?? undefined,
        borderColor: borderColor ?? undefined,
        borderWidth: borderWidth ?? undefined,
        borderRadius: borderRadius ?? undefined,
      };
    default: {
      unreachable(type);
      return {
        type,
        accentColor: accentColor ?? undefined,
      };
    }
  }
};
