import { SMART_BLOCK_TYPE, TIPTAP_COLLAPSIBLE_LIST_TYPE } from './../ricos-content/consts.js';
import type { EditorPluginCreator, RicosServices, ToolbarButton } from './../ricos-types/index.js';
import { RicosPluginToolbarNames } from './../ricos-types/index.js';
import { PmNodeType } from './../_shared/pm-node-types.js';
import { findParentNodeClosestToPos } from './../tiptap/core.js';
import type { NodeSelection, Selection } from './../tiptap/pm/state.js';

import { getAddButtons } from './get-add-buttons.js';
import { getQuickActions } from './get-quick-actions.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { smartBlockCellConverter } from './smart-block-cell-converter.js';
import { smartBlockConverter } from './smart-block-converter.js';
import { smartBlockCellExtension } from './tiptap/smart-block-cell-extension.js';
import { smartBlockExtension } from './tiptap/smart-block-extension.js';
import { resolveSmartBlockReferenceElement } from './toolbar/resolve-smart-block-reference-element.js';
import type { SmartBlockPluginEditorConfig } from './types.js';
export { resolveSmartBlockReferenceElement } from './toolbar/resolve-smart-block-reference-element.js';

export const pluginSmartBlock: EditorPluginCreator<SmartBlockPluginEditorConfig> = (
  config = {} as SmartBlockPluginEditorConfig
) => {
  return {
    config: { ...config, type: 'smartBlock' as const },
    type: SMART_BLOCK_TYPE,
    pmMarkConverters: [],
    pmNodeConverters: [smartBlockConverter, smartBlockCellConverter],
    tiptapExtensions: [smartBlockExtension, smartBlockCellExtension],
    toolbar: {
      names: [RicosPluginToolbarNames.SMART_BLOCK, RicosPluginToolbarNames.SMART_BLOCK_CELL],
      isVisible: isToolbarVisible,
      getButtons: (
        config: SmartBlockPluginEditorConfig | undefined,
        services: RicosServices
      ): ToolbarButton[] => getToolbarButtons(config, services),
      resolveReferenceElement: resolveSmartBlockReferenceElement,
    },
    getAddButtons: (config, services) => getAddButtons(config, services),
    getQuickActions: ({ pluginServices, config }) => getQuickActions(config, pluginServices),
  };
};

const isToolbarVisible = (selection: Selection | NodeSelection): boolean => {
  // Show toolbar when layout container is selected
  if ('node' in selection && selection.node?.type.name === PmNodeType.SMART_BLOCK) {
    return true;
  }

  // Show toolbar when a cell is selected
  if ('node' in selection && selection.node?.type.name === PmNodeType.SMART_BLOCK_CELL) {
    return true;
  }

  if ('node' in selection) {
    return false;
  }

  // Defer to nested plugins that own their own subtree toolbar (e.g. collapsible list).
  // If a nested container is closer to the selection than the smart block, that plugin wins.
  const closestContainer = findParentNodeClosestToPos(
    selection.$from,
    node =>
      node.type.name === PmNodeType.SMART_BLOCK || node.type.name === TIPTAP_COLLAPSIBLE_LIST_TYPE
  );

  return closestContainer?.node.type.name === PmNodeType.SMART_BLOCK;
};
