import type { PmNodeConverter, PmNodeJson } from './../pm-converters/types.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type {
  SmartBlockCellNode,
  SmartBlockData,
  SmartBlockNode,
} from './../ricos-schema/next-schema/index.js';
import type { PmSmartBlockNode } from './../_shared/pm-node-types.js';
import { unreachable } from './../_shared/uncreachable.js';

import { SMART_BLOCK_DEFAULTS } from './consts.js';

export const smartBlockConverter: PmNodeConverter = {
  toPm: {
    types: [Node_Type.SMART_BLOCK],
    // @ts-expect-error next node type
    convert: (
      node: SmartBlockNode,
      visit: (node: SmartBlockNode | SmartBlockCellNode) => PmNodeJson[]
    ) => {
      const data = node.smartBlockData as any;
      return {
        type: Node_Type.SMART_BLOCK,
        attrs: {
          id: node.id,
          type: data?.type ?? SMART_BLOCK_DEFAULTS.type,
          columnSize: data?.columnSize ?? SMART_BLOCK_DEFAULTS.columnSize,
          orientation: data?.orientation ?? null,
          backgroundColor: data?.backgroundColor ?? null,
          borderColor: data?.borderColor ?? null,
          borderWidth: data?.borderWidth ?? null,
          borderRadius: data?.borderRadius ?? null,
          animation: data?.animation ?? null,
        },
        content: visit(node),
      };
    },
  },
  fromPm: {
    types: [Node_Type.SMART_BLOCK],
    // @ts-expect-error next node type
    convert: (node: PmNodeJson, visit?: (node: PmNodeJson) => SmartBlockNode[]) => {
      const { attrs } = node as unknown as PmSmartBlockNode;
      const { id } = attrs;

      return {
        type: Node_Type.SMART_BLOCK,
        id,
        smartBlockData: {
          ...smartBlockDataPerVariant(attrs),
          // covers all variants in one place
          ...(attrs.animation ? { animation: attrs.animation } : {}),
        },
        nodes: visit?.(node),
      };
    },
  },
};

const smartBlockDataPerVariant = (attrs: PmSmartBlockNode['attrs']): SmartBlockData => {
  const { columnSize, orientation, borderColor, borderWidth, borderRadius } = attrs;
  const type = attrs.type ?? SMART_BLOCK_DEFAULTS.type;
  switch (type) {
    case 'SOLID_BOXES':
    case 'STATS':
    case 'BAR_STATS':
    case 'CIRCLE_STATS':
    case 'SIDE_LINE_TEXT':
    case 'TOP_LINE_TEXT':
    case 'NUMBERED_BOXES':
    case 'OUTLINE_BOXES_WITH_TOP_CIRCLE':
    case 'PROCESS_STEPS':
    case 'STAR_RATING':
    case 'QUOTE_BOXES':
    case 'CIRCLE':
    case 'PYRAMID':
    case 'STAIRCASE':
    case 'VERTICAL_FUNNEL':
      return {
        type,
        columnSize: columnSize ?? undefined,
      };
    case 'SOLID_BOXES_ALTERNATING':
    case 'SMALL_BULLETS':
    case 'ARROW_BULLETS':
    case 'TIMELINE':
    case 'MINIMAL_TIMELINE':
    case 'PILLS':
      return {
        type,
        columnSize: columnSize ?? undefined,
        orientation: orientation ?? undefined,
      };
    case 'BIG_BULLETS':
      return {
        type,
        columnSize: columnSize ?? undefined,
        orientation: orientation ?? undefined,
      };
    case 'SOLID_JOINED_BOXES':
      return {
        type,
        columnSize: columnSize ?? undefined,
        borderColor: borderColor ?? undefined,
        borderWidth: borderWidth ?? undefined,
        borderRadius: borderRadius ?? undefined,
      };
    default: {
      unreachable(type);
      return {
        type,
        columnSize: columnSize ?? undefined,
      };
    }
  }
};
