import type {
  Media,
  SmartBlockCellData,
  SmartBlockData,
  SmartBlockData_Orientation,
  SmartBlockData_Type,
} from './../../ricos-schema/next-schema/index.js';

export const isBulletVariant = (
  type: SmartBlockData_Type
): type is 'BIG_BULLETS' | 'ARROW_BULLETS' | 'SMALL_BULLETS' =>
  ['BIG_BULLETS', 'ARROW_BULLETS', 'SMALL_BULLETS'].includes(type);

type HasShapeSupport = Extract<SmartBlockCellData, { shape?: Media }>['type'];

export const hasShapeSupport = (
  type: SmartBlockCellData['type']
): type is Extract<SmartBlockCellData['type'], HasShapeSupport> =>
  (
    [
      'NUMBERED_BOXES',
      'OUTLINE_BOXES_WITH_TOP_CIRCLE',
      'BIG_BULLETS',
      'ARROW_BULLETS',
      'PROCESS_STEPS',
      'TIMELINE',
      'PILLS',
      'CIRCLE',
      'PYRAMID',
      'STAIRCASE',
      'VERTICAL_FUNNEL',
    ] as const satisfies HasShapeSupport[]
  ).includes(type as HasShapeSupport);

type HasCellBorderSupport = Extract<SmartBlockCellData, { borderColor?: string }>['type'];

export const hasCellBorderSupport = (
  type: SmartBlockCellData['type']
): type is Extract<SmartBlockCellData['type'], HasCellBorderSupport> =>
  (
    [
      'SOLID_BOXES',
      'NUMBERED_BOXES',
      'STATS',
      'SOLID_BOXES_ALTERNATING',
      'BIG_BULLETS',
      'SMALL_BULLETS',
      'ARROW_BULLETS',
    ] as const satisfies HasCellBorderSupport[]
  ).includes(type as HasCellBorderSupport);

type HasBlockBorderSupport = Extract<SmartBlockData, { borderColor?: string }>['type'];

export const hasBlockBorderSupport = (
  type: SmartBlockData['type']
): type is Extract<SmartBlockData['type'], HasBlockBorderSupport> =>
  (['SOLID_JOINED_BOXES'] as const satisfies HasBlockBorderSupport[]).includes(
    type as HasBlockBorderSupport
  );

type HasOrientation = Extract<SmartBlockData, { orientation?: SmartBlockData_Orientation }>['type'];

export const hasOrientation = (
  type: SmartBlockData['type']
): type is Extract<SmartBlockData['type'], HasOrientation> =>
  (
    [
      'SOLID_BOXES_ALTERNATING',
      'BIG_BULLETS',
      'SMALL_BULLETS',
      'ARROW_BULLETS',
      'TIMELINE',
      'MINIMAL_TIMELINE',
      'PILLS',
    ] as const satisfies HasOrientation[]
  ).includes(type as HasOrientation);

// Whether the variant exposes a column-size choice in the editor toolbar. Can't
// be derived from the schema: the proto `SmartBlockData` carries `column_size`
// as a flat field on every variant (proto3 enums always read back with a value,
// so absent ≡ `SMALL`), and the JTD mirrors that for proto parity. So the list
// of variants that don't support column-size lives here, hand-maintained.
export const hasColumnSizeSupport = (type: SmartBlockData_Type): boolean => {
  switch (type) {
    case 'SOLID_BOXES_ALTERNATING':
    case 'TIMELINE':
    case 'MINIMAL_TIMELINE':
    case 'PYRAMID':
    case 'STAIRCASE':
    case 'CIRCLE':
      return false;
    default:
      return true;
  }
};

type HasBackgroundColor = Extract<SmartBlockCellData, { backgroundColor?: string }>['type'];

export const getCellColorAttr = (
  type: SmartBlockCellData['type']
): 'backgroundColor' | 'accentColor' =>
  (
    [
      'SOLID_BOXES',
      'SOLID_BOXES_ALTERNATING',
      'SOLID_JOINED_BOXES',
    ] as const satisfies HasBackgroundColor[]
  ).includes(type as HasBackgroundColor)
    ? 'backgroundColor'
    : 'accentColor';
