import { mapColorPaletteToCustomStyles } from './../../ricos-styles/themeStrategy/generators/palette.js';
import type { RicosTheme } from './../../ricos-types/index.js';

// Resolves the smart-block custom style from either the explicit customStyles
// override or, failing that, the derived colorPalette mapping. Returns undefined
// when neither is available.
export const resolveThemeSmartBlock = (theme: RicosTheme) =>
  theme.customStyles?.smartBlock ??
  (theme.colorPalette ? mapColorPaletteToCustomStyles(theme.colorPalette).smartBlock : undefined);
