import type { FC } from 'react';
import React, { useContext, useMemo } from 'react';

import {
  RicosAlignmentContextProvider,
  RicosContext,
  RicosNodeContext,
  RicosNodeContextProvider,
} from './../../ricos-context/index.js';
import type { SmartBlockCellNode, SmartBlockNode } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRenderer, NodeViewRendererProps, TextAlignment } from './../../ricos-types/index.js';

import { SmartBlockCellView } from '../components/smart-block-cell-view.js';
import { SMART_BLOCK_DEFAULTS } from '../consts.js';
import { getCircleCellStyle } from '../utils/cell-position.js';
import { ricosCellToViewModel } from '../utils/cell-view-model.js';
import { resolveThemeSmartBlock } from '../utils/resolve-theme-smart-block.js';

// Lowercase values intentionally don't match alignmentStyle's uppercase keys
// (paragraph.tsx → alignment.scss), so AUTO paragraphs in CIRCLE cells render
// without an `.AUTO` class — inheriting cell text-align instead of clobbering
// it with `text-align: initial`. Editor (no inline style for AUTO) already
// inherits; this restores the same behavior in the viewer.
const CIRCLE_SIDE_TO_ALIGNMENT: Record<'left' | 'right' | 'bottom', TextAlignment> = {
  left: 'right',
  right: 'left',
  bottom: 'center',
};

const SmartBlockCellViewer: FC<NodeViewRendererProps> = ({
  node,
  nodeIndex: cellIndex,
  RicosNodesRenderer,
}) => {
  const cellNode = node as SmartBlockCellNode;

  const { theme } = useContext(RicosContext);
  const themeSmartBlock = useMemo(() => resolveThemeSmartBlock(theme), [theme]);

  // The viewer's RicosNodeContextProvider (set up in SmartBlockViewer) exposes
  // the parent block node. Cell-level state (type / columnSize / orientation /
  // totalCells / isShapesMode) is derived from it locally — no block-level
  // smart-block context exists in this design.
  const nodeContext = useContext(RicosNodeContext) ?? {};
  const parentNode = nodeContext.parentNode as SmartBlockNode | undefined;
  const smartBlockData = parentNode?.smartBlockData;
  const type = smartBlockData?.type ?? SMART_BLOCK_DEFAULTS.type;
  const columnSize =
    smartBlockData && 'columnSize' in smartBlockData
      ? (smartBlockData?.columnSize ?? SMART_BLOCK_DEFAULTS.columnSize)
      : SMART_BLOCK_DEFAULTS.columnSize;
  const orientation = (
    smartBlockData && 'orientation' in smartBlockData ? smartBlockData.orientation : 'HORIZONTAL'
  ) as 'HORIZONTAL' | 'VERTICAL';
  const isShapesMode = !!parentNode?.nodes?.some(
    n =>
      n.type === 'SMART_BLOCK_CELL' &&
      n.smartBlockCellData !== null &&
      n.smartBlockCellData !== undefined &&
      'shape' in n.smartBlockCellData &&
      n.smartBlockCellData.shape !== null &&
      n.smartBlockCellData.shape !== undefined
  );
  const totalCells = parentNode?.nodes?.length ?? 1;

  const viewModel = useMemo(
    () =>
      ricosCellToViewModel(cellNode, {
        type,
        columnSize,
        orientation,
        totalCells,
        cellIndex,
        isShapesMode,
      }),
    [cellNode, type, columnSize, orientation, totalCells, cellIndex, isShapesMode]
  );

  const circleAlignment =
    type === 'CIRCLE'
      ? CIRCLE_SIDE_TO_ALIGNMENT[getCircleCellStyle(cellIndex, totalCells).side]
      : undefined;

  return (
    <SmartBlockCellView
      viewModel={viewModel}
      themeSmartBlock={themeSmartBlock}
      contentSlot={contentProps => {
        const renderer = (
          <RicosNodesRenderer
            key={`children-${node.id}`}
            nodes={node.nodes ?? []}
            shouldParagraphApplyTextStyle
          />
        );
        return (
          <div {...contentProps}>
            <RicosNodeContextProvider parentNode={node} parentIndex={cellIndex}>
              {circleAlignment ? (
                <RicosAlignmentContextProvider textAlignment={circleAlignment}>
                  {renderer}
                </RicosAlignmentContextProvider>
              ) : (
                renderer
              )}
            </RicosNodeContextProvider>
          </div>
        );
      }}
    />
  );
};

const SmartBlockCellRenderer: NodeViewRenderer = ({ node, ...props }) => {
  return <SmartBlockCellViewer key={node.id} node={node} {...props} />;
};

export default SmartBlockCellRenderer;
