import { createContext, useContext } from 'react';
import type React from 'react';

// Editor-only callbacks. Provided ONLY by the editor side. The viewer leaves
// this context unset — accessory components fall back to viewer-only rendering
// when the context is null.
type SmartBlockCellEditorContextValue = {
  onLabelChange: (label: string | null) => void;
  onShapeClick: (event: React.MouseEvent<HTMLButtonElement>) => void;
};

export const SmartBlockCellEditorContext = createContext<SmartBlockCellEditorContextValue | null>(
  null
);

// Returns null in the viewer (where the context isn't set up).
export const useSmartBlockCellEditorContext = (): SmartBlockCellEditorContextValue | null =>
  useContext(SmartBlockCellEditorContext);

// Block-level editor-only callbacks. Mirrors the cell-level context above —
// editor provides, viewer leaves unset. Consumed by SmartBlockView to open the
// per-cell shape picker for accessories that live OUTSIDE the per-cell context
// (the CIRCLE donut indicators and the STAIRCASE mobile-stack bars), so they
// can't use the cell-level `onShapeClick` and pass the cellId explicitly. Typed
// with the MouseEvent base so a PointerEvent (from ShapeOverlay) fits too.
type SmartBlockEditorContextValue = {
  onCellShapeClick: (cellId: string, event: React.MouseEvent<HTMLButtonElement>) => void;
};

export const SmartBlockEditorContext = createContext<SmartBlockEditorContextValue | null>(null);

export const useSmartBlockEditorContext = (): SmartBlockEditorContextValue | null =>
  useContext(SmartBlockEditorContext);

// The shape-picker affordance the editor paints over a cell / slice / donut
// indicator. It arrives through context rather than a shared import because
// `ShapeOverlay` renders a WDS `ToggleButton`, and all three components that
// render it (`smart-block-cell-view`, `smart-block-view`, `circle-donut`) are
// also reachable from `plugin-smart-block/viewer.ts` — so a static import ships
// `@wix/design-system` to every live site even though the viewer never paints
// the overlay. See ground rule 2 of the WDS migration, enforced by
// `scripts/verify-viewer-graph.ts`.
//
// Provided by both editor node views (`tiptap/smart-block.tsx` and
// `tiptap/smart-block-cell.tsx` — tiptap renders each node view into its own
// React root, so context does not flow between them). Left unset by the viewer,
// which then renders no overlay, exactly as the `onShapeClick` guards did.
export type ShapeOverlayProps = {
  overlayClassName: string;
  hasShape: boolean;
  onClick: (event: React.MouseEvent<HTMLButtonElement>) => void;
};

export const ShapeOverlayContext = createContext<React.ComponentType<ShapeOverlayProps> | null>(
  null
);

export const useShapeOverlay = (): React.ComponentType<ShapeOverlayProps> | null =>
  useContext(ShapeOverlayContext);
