import type { FileSource, Media } from './../../ricos-schema/next-schema/index.js';

import { DEFAULT_SHAPE_SRC } from '../consts.js';

export const resolveShapeSrc = (image: Media | undefined): FileSource => {
  const src = image?.src;
  if (typeof src === 'string') {
    return { url: src };
  }
  return src ?? DEFAULT_SHAPE_SRC;
};
