import {
  Node_Type,
  type Media,
  type SmartBlockCellNode,
  type SmartBlockData_Orientation,
  type SmartBlockData_Type,
  type SmartBlockNode,
} from './../../ricos-schema/next-schema/index.js';
import {
  PmNodeType,
  type PmSmartBlockCellNode,
  type PmSmartBlockNode,
} from './../../_shared/pm-node-types.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';

import { SMART_BLOCK_DEFAULTS } from '../consts.js';

// Per-cell data for the variants that render a cell-derived accessory outside
// the normal content flow: CIRCLE's <CircleDonut> segments, STAIRCASE's mobile
// bar stack, and the triangle family's (PYRAMID / VERTICAL_FUNNEL) cohesive
// mobile slice stack. They all need the same fields (accent + shape), so one
// shape (and one PM/JTD extractor pair below) serves every variant — only the
// SCSS clip-path / layout differs. Carried here rather than discovered via DOM
// lookup from each cell — the block view already has access to its children's
// attrs through PM/JTD.
export type SmartBlockCellRenderData = {
  // PM always sets a cell id; JTD's optional. Consumers need it to target the
  // shape / segment-indicator picker at the right cell.
  cellId?: string;
  accentColor?: string;
  shape?: Media;
  shapeColor?: string;
};

// Normalised block-wrapper shape consumed by SmartBlockView. PM (editor) and
// JTD (viewer) each have an adapter that maps their native node to this same
// shape, so the renderer no longer branches on data source.
export type BlockViewModel = {
  type: SmartBlockData_Type;
  columnSize: string;
  orientation?: SmartBlockData_Orientation;
  totalCells: number;

  // Wrapper border. Only SOLID_JOINED_BOXES carries these on its schema; the
  // CSS-var emitter in `computeSmartBlockWrapperVars` ignores them for other
  // variants so the adapter can hand them off unconditionally.
  blockBorder: {
    borderColor?: string;
    borderWidth?: number;
    borderRadius?: number;
  };

  // Undefined for every variant except CIRCLE / STAIRCASE / PYRAMID /
  // VERTICAL_FUNNEL — gates accessory rendering in SmartBlockView without a
  // second iteration over cells.
  cells?: SmartBlockCellRenderData[];
};

const nullToUndef = <T>(value: T | null | undefined): T | undefined =>
  value === null || value === undefined ? undefined : value;

const hasCellRenderData = (type: SmartBlockData_Type): boolean =>
  type === 'CIRCLE' || type === 'STAIRCASE' || type === 'PYRAMID' || type === 'VERTICAL_FUNNEL';

const pmCells = (pmNode: PmNode): SmartBlockCellRenderData[] => {
  const cells: SmartBlockCellRenderData[] = [];
  pmNode.forEach(child => {
    if (child.type.name === PmNodeType.SMART_BLOCK_CELL) {
      const attrs = child.attrs as PmSmartBlockCellNode['attrs'];
      cells.push({
        cellId: nullToUndef(attrs.id),
        accentColor: nullToUndef(attrs.accentColor),
        shape: attrs.shape,
        shapeColor: nullToUndef(attrs.shapeColor),
      });
    }
  });
  return cells;
};

const jtdCells = (node: SmartBlockNode): SmartBlockCellRenderData[] =>
  (node.nodes ?? [])
    .filter((n): n is SmartBlockCellNode => n.type === Node_Type.SMART_BLOCK_CELL)
    .map(cell => {
      const data = cell.smartBlockCellData;
      return {
        cellId: cell.id,
        accentColor: data && 'accentColor' in data ? data.accentColor : undefined,
        shape: data && 'shape' in data ? data.shape : undefined,
        shapeColor: data && 'shapeColor' in data ? data.shapeColor : undefined,
      };
    });

export const pmBlockToViewModel = (pmNode: PmNode): BlockViewModel => {
  const attrs = pmNode.attrs as PmSmartBlockNode['attrs'];
  const type = attrs.type ?? SMART_BLOCK_DEFAULTS.type;
  return {
    type,
    columnSize: attrs.columnSize ?? SMART_BLOCK_DEFAULTS.columnSize,
    orientation: nullToUndef(attrs.orientation),
    totalCells: pmNode.childCount,
    blockBorder: {
      borderColor: nullToUndef(attrs.borderColor),
      borderWidth: nullToUndef(attrs.borderWidth),
      borderRadius: nullToUndef(attrs.borderRadius),
    },
    cells: hasCellRenderData(type) ? pmCells(pmNode) : undefined,
  };
};

export const jtdBlockToViewModel = (node: SmartBlockNode): BlockViewModel => {
  const data = node.smartBlockData;
  const type = data?.type ?? SMART_BLOCK_DEFAULTS.type;
  return {
    type,
    columnSize:
      data && 'columnSize' in data
        ? (data.columnSize ?? SMART_BLOCK_DEFAULTS.columnSize)
        : SMART_BLOCK_DEFAULTS.columnSize,
    orientation:
      data && 'orientation' in data
        ? (data.orientation as SmartBlockData_Orientation | undefined)
        : undefined,
    totalCells: node.nodes?.length ?? 0,
    blockBorder: {
      borderColor: data && 'borderColor' in data ? data.borderColor : undefined,
      borderWidth: data && 'borderWidth' in data ? data.borderWidth : undefined,
      borderRadius: data && 'borderRadius' in data ? data.borderRadius : undefined,
    },
    cells: hasCellRenderData(type) ? jtdCells(node) : undefined,
  };
};
