export type CellNumericValue = {
  rawLabel: string;
  parsedValue: number | null;
  clampedValue: number;
  hasParsedValue: boolean;
};

const NUMERIC_VALUE_PATTERN = /-?\d+(?:\.\d+)?/;
const DEFAULT_MAX = 100;

export const getCellNumericValue = (
  label?: string | null,
  options?: { max?: number }
): CellNumericValue => {
  const rawLabel = label ?? '';
  const match = rawLabel.match(NUMERIC_VALUE_PATTERN);

  if (!match) {
    return {
      rawLabel,
      parsedValue: null,
      clampedValue: 0,
      hasParsedValue: false,
    };
  }

  const parsedValue = Number(match[0]);

  if (!Number.isFinite(parsedValue) || parsedValue < 0) {
    return {
      rawLabel,
      parsedValue: null,
      clampedValue: 0,
      hasParsedValue: false,
    };
  }

  return {
    rawLabel,
    parsedValue,
    clampedValue: Math.min(parsedValue, options?.max ?? DEFAULT_MAX),
    hasParsedValue: true,
  };
};
