import type { FC } from 'react';
import React, { useContext, useMemo } from 'react';

import { RicosContext, RicosNodeContextProvider } from './../../ricos-context/index.js';
import { type SmartBlockNode } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRenderer, NodeViewRendererProps } from './../../ricos-types/index.js';

import { SmartBlockView } from '../components/smart-block-view.js';
import { jtdBlockToViewModel } from '../utils/block-view-model.js';
import { resolveThemeSmartBlock } from '../utils/resolve-theme-smart-block.js';

const SmartBlockViewer: FC<NodeViewRendererProps> = ({ node, nodeIndex, RicosNodesRenderer }) => {
  const smartBlockNode = node as SmartBlockNode;
  const { theme } = useContext(RicosContext);
  const themeSmartBlock = useMemo(() => resolveThemeSmartBlock(theme), [theme]);
  const viewModel = useMemo(() => jtdBlockToViewModel(smartBlockNode), [smartBlockNode]);

  return (
    <SmartBlockView
      viewModel={viewModel}
      themeSmartBlock={themeSmartBlock}
      contentSlot={innerProps => (
        <div {...innerProps}>
          <RicosNodeContextProvider parentNode={node} parentIndex={nodeIndex}>
            <RicosNodesRenderer key={`children-${node.id}`} nodes={node.nodes ?? []} />
          </RicosNodeContextProvider>
        </div>
      )}
    />
  );
};

const SmartBlockRenderer: NodeViewRenderer = ({ node, ...props }) => {
  return <SmartBlockViewer key={node.id} node={node} {...props} />;
};

export default SmartBlockRenderer;
