export const getJoinedBoxesResponsiveCornerFlags = ({
  cellIndex,
  totalCells,
  columnsPerRow,
  responsiveColumnsPerRow,
}: {
  cellIndex: number;
  totalCells: number;
  columnsPerRow: number;
  responsiveColumnsPerRow: number;
}): Record<string, true | undefined> => {
  const base = getJoinedBoxesCellCornerFlags({ cellIndex, totalCells, columnsPerRow });
  const mid = getJoinedBoxesCellCornerFlags({
    cellIndex,
    totalCells,
    columnsPerRow: responsiveColumnsPerRow,
  });
  const sm = getJoinedBoxesCellCornerFlags({ cellIndex, totalCells, columnsPerRow: 1 });

  return {
    ...base,
    'data-corner-mid-tl': mid['data-corner-tl'],
    'data-corner-mid-tr': mid['data-corner-tr'],
    'data-corner-mid-bl': mid['data-corner-bl'],
    'data-corner-mid-br': mid['data-corner-br'],
    'data-corner-sm-tl': sm['data-corner-tl'],
    'data-corner-sm-tr': sm['data-corner-tr'],
    'data-corner-sm-bl': sm['data-corner-bl'],
    'data-corner-sm-br': sm['data-corner-br'],
  };
};

const getJoinedBoxesCellCornerFlags = ({
  cellIndex,
  totalCells,
  columnsPerRow,
}: {
  cellIndex: number;
  totalCells: number;
  columnsPerRow: number;
}): Record<string, true | undefined> => {
  const topRight = Math.min(columnsPerRow - 1, totalCells - 1);
  const lastRowStart = Math.floor((totalCells - 1) / columnsPerRow) * columnsPerRow;

  return {
    'data-corner-tl': cellIndex === 0 || undefined,
    'data-corner-tr': cellIndex === topRight || undefined,
    'data-corner-bl': cellIndex === lastRowStart || undefined,
    'data-corner-br': cellIndex === totalCells - 1 || undefined,
  };
};
