import { LayoutTwoColumns } from '@wix/wix-ui-icons-common/lazy';

import type { PluginServices } from './../ricos-plugins/editor-plugins.js';
import { Node_Type, type QuickAction, quickActionsModalSections } from './../ricos-types/index.js';
import { posToDOMRect } from './../tiptap/core/index.js';

import { SMART_BLOCK_VARIANT_PICKER_MODAL_ID, VariantPicker } from './modals/variant-picker.js';
import type { SmartBlockPluginEditorConfig } from './types.js';

export const getQuickActions = (
  _config: SmartBlockPluginEditorConfig,
  pluginServices: PluginServices
): QuickAction[] => [
  {
    id: Node_Type.SMART_BLOCK,
    title: 'SmartBlock_InsertButton_Label',
    icon: LayoutTwoColumns,
    section: quickActionsModalSections.FormatLayout,
    tags: ['layout', 'grid', 'boxes', 'cards', 'columns', 'features'],
    command: ({ modalService, editor, referenceElement }) => {
      modalService.togglePluginPanel({
        id: SMART_BLOCK_VARIANT_PICKER_MODAL_ID,
        Component: VariantPicker,
        componentProps: {},
        isMobile: pluginServices.context.isMobile,
        positioning: {
          referenceElement: referenceElement ?? {
            getBoundingClientRect: () =>
              posToDOMRect(
                editor.view,
                editor.view.state.selection.from,
                editor.view.state.selection.to
              ),
          },
          placement: 'bottom-start',
        },
      });
    },
  },
];
